const IMGS={"interior": "data:image/jpeg;base64,", "grill": "data:image/jpeg;base64,", "menu": "data:image/jpeg;base64,", "front": "data:image/jpeg;base64,"};
document.querySelectorAll('img[data-img]').forEach(i=>{i.src=IMGS[i.dataset.img]});
const MENU={
 "Mangal Dönər":[["Ət dönər, çörəkdə","3.40"],["Ət dönər, lavaş","3.60"],["Tombik","4.00"],["Limuzin","4.00"],["Bastırma","4.00"],["Persian","4.00"],["Plevüstü","7.80"],["İskəndər","8.80"],["Hatay üsulu","8.00"],["Hatay pendirli","6.50"]],
 "Kabab":[["Kabab çəki ilə — ətli (1 kq)","49.00"],["Kabab çəki ilə — toyuq (1 kq)","29.00"],["Menyuda daha çox növ","—"]],
 "Lahmacun":[["Lahmacun","3.00"],["Lahmacun qaşlı","3.20"],["Lahmacun pendirli","3.40"],["Lahmacun qarışıq","3.60"],["Antep lahmacun","3.40"],["Urfa lahmacun","3.40"]],
 "Pide":[["Pendirli","6.80"],["Qıymalı","6.00"],["Ət kuşbaşı","7.80"],["Toyuq kuşbaşı","6.80"],["Qarışıq","8.40"],["Qapalı","7.40"],["Sucuklu","7.80"],["İspanaqlı","6.80"]],
 "Burger":[["Şaurma (ət, çörəkdə)","5.00"],["Şaurma (ət, lavaş)","5.00"],["Şaurma (toyuq, çörəkdə)","4.00"],["Şaurma (toyuq, lavaş)","4.40"],["Toyuq burger","5.00"],["Ət burger","6.00"],["BBQ burger","10.00"],["Şnitsel","9.00"],["Fri","2.50"],["Nuggets (4 ədəd)","5.00"]],
 "Şirniyyat":[["Bakı paxlavası","5.00"],["Türk paxlavası","4.00"],["Tort","5.00"]],
 "İçkilər":[["Coca-Cola 0.3 L","1.20"],["Coca-Cola 0.5 L","1.60"],["Coca-Cola 1 L","2.20"],["Coca-Cola 2 L","3.00"],["Fanta 0.3 L","1.20"],["Sprite 0.3 L","1.20"],["Ayran","0.70"],["Qazlı / qazsız su","0.80"],["Meyvə suyu","1.00"]]
};
const tabs=document.getElementById('tabs'),grid=document.getElementById('menuGrid');
function show(k){
  [...tabs.children].forEach(t=>t.classList.toggle('on',t.textContent===k));
  grid.innerHTML=MENU[k].map(([n,p])=>`<div class="item"><span class="n">${n}</span><span class="dots"></span><span class="p">${p==='—'?p:p+' ₼'}</span></div>`).join('');
}
Object.keys(MENU).forEach(k=>{const b=document.createElement('button');b.className='tab';b.textContent=k;b.onclick=()=>show(k);tabs.appendChild(b)});
show('Mangal Dönər');
document.querySelectorAll('.cat').forEach(c=>c.onclick=()=>{show(c.dataset.go);document.getElementById('menu').scrollIntoView({behavior:'smooth'})});

const nav=document.getElementById('nav'),links=document.getElementById('links');
addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>40),{passive:true});
document.getElementById('burger').onclick=()=>links.classList.toggle('open');
links.querySelectorAll('a').forEach(a=>a.onclick=()=>links.classList.remove('open'));

const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.15});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));

document.getElementById('form').onsubmit=e=>{e.preventDefault();document.getElementById('ok').style.display='block';e.target.reset()};
document.getElementById('y').textContent=new Date().getFullYear();

const lb=document.getElementById('lb'),lbimg=document.getElementById('lbimg');
document.addEventListener('click',e=>{
  const z=e.target.closest('[data-zoom]');
  if(!z)return;
  const im=z.tagName==='IMG'?z:z.querySelector('img');
  if(!im||!im.src)return;
  lbimg.src=im.src;lbimg.alt=im.alt;lb.classList.add('on');
});
lb.onclick=()=>lb.classList.remove('on');
addEventListener('keydown',e=>{if(e.key==='Escape')lb.classList.remove('on')});
